package io.invenlio.inventory;
import io.invenlio.catalog.CatalogInventoryLookup;import io.invenlio.organization.*;import java.sql.*;import java.time.*;import java.util.*;import org.springframework.context.ApplicationEventPublisher;import org.springframework.dao.DataIntegrityViolationException;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
@Service class TraceabilityService{
 private final AuthorizationService auth;private final AuditTrail audit;private final CatalogInventoryLookup catalog;private final JdbcTemplate jdbc;private final ApplicationEventPublisher events;TraceabilityService(AuthorizationService a,AuditTrail au,CatalogInventoryLookup c,JdbcTemplate j,ApplicationEventPublisher e){auth=a;audit=au;catalog=c;jdbc=j;events=e;}
 @Transactional LotView createLot(LotCommand c){var a=auth.require(Permission.INVENTORY_TRACEABILITY_MANAGE);var v=variant(a.tenantId(),c.variantId);if(!Set.of("LOT","LOT_AND_SERIAL").contains(v.trackingMode()))throw error("LOT_NOT_ALLOWED","Variant does not support lots");String n=normalize(c.lotNumber,"lot");if(v.expirationRequired()&&c.expiresOn==null)throw error("INVALID_LOT_DATES","Expiry is required");dates(c.manufacturedOn,c.expiresOn);UUID id=UUID.randomUUID();try{jdbc.update("INSERT INTO inventory_lots(id,tenant_id,variant_id,lot_number,normalized_lot_number,manufactured_on,expires_on,status,created_at,updated_at,version)VALUES (?,?,?,?,?,?,?,'ACTIVE',now(),now(),0)",id,a.tenantId(),c.variantId,c.lotNumber.trim(),n,c.manufacturedOn,c.expiresOn);}catch(DataIntegrityViolationException e){throw error("LOT_ALREADY_EXISTS","Lot already exists");}audit.record(a,"LOT_CREATED","inventory-lot",id.toString());events.publishEvent(new TraceabilityEvents.LotCreated(a.tenantId(),id,c.variantId));return lot(a.tenantId(),id);}
 @Transactional SerialView createSerial(SerialCommand c){var a=auth.require(Permission.INVENTORY_TRACEABILITY_MANAGE);var v=variant(a.tenantId(),c.variantId);if(!Set.of("SERIAL","LOT_AND_SERIAL").contains(v.trackingMode()))throw error("SERIAL_NOT_ALLOWED","Variant does not support serials");if(v.trackingMode().equals("LOT_AND_SERIAL")&&c.lotId==null)throw error("LOT_REQUIRED","Lot is required");if(v.trackingMode().equals("SERIAL")&&c.lotId!=null)throw error("LOT_NOT_ALLOWED","Lot is not allowed");if(c.lotId!=null)lotFor(a.tenantId(),c.variantId,c.lotId);String n=normalize(c.serialNumber,"serial");UUID id=UUID.randomUUID();try{jdbc.update("INSERT INTO inventory_serials(id,tenant_id,variant_id,serial_number,normalized_serial_number,lot_id,status,created_at,updated_at,version)VALUES (?,?,?,?,?,?,'ACTIVE',now(),now(),0)",id,a.tenantId(),c.variantId,c.serialNumber.trim(),n,c.lotId);}catch(DataIntegrityViolationException e){throw error("SERIAL_ALREADY_EXISTS","Serial already exists");}audit.record(a,"SERIAL_CREATED","inventory-serial",id.toString());events.publishEvent(new TraceabilityEvents.SerialCreated(a.tenantId(),id,c.variantId));return serial(a.tenantId(),id);}
 @Transactional(readOnly=true)List<LotView>lots(UUID variant,String status,String number,int page,int size,String sort){var a=auth.require(Permission.INVENTORY_TRACEABILITY_READ);bounds(page,size);String order=switch(sort==null?"createdAt":sort){case"lotNumber"->"normalized_lot_number";case"expiresOn"->"expires_on NULLS LAST";case"createdAt"->"created_at";default->throw error("INVALID_SORT","Unsupported lot sort");};return jdbc.query("SELECT id,variant_id,lot_number,manufactured_on,expires_on,status,created_at,updated_at,version FROM inventory_lots WHERE tenant_id=? AND (?::uuid IS NULL OR variant_id=?::uuid) AND (?::text IS NULL OR status=?::text) AND (?::text IS NULL OR normalized_lot_number=upper(trim(?::text))) ORDER BY "+order+",id OFFSET ? LIMIT ?",this::lotRow,a.tenantId(),variant,variant,status,status,number,number,page*size,size);}
 @Transactional(readOnly=true)List<SerialView>serials(UUID variant,UUID lot,String status,String number,int page,int size,String sort){var a=auth.require(Permission.INVENTORY_TRACEABILITY_READ);bounds(page,size);String order=switch(sort==null?"createdAt":sort){case"serialNumber"->"normalized_serial_number";case"createdAt"->"created_at";default->throw error("INVALID_SORT","Unsupported serial sort");};return jdbc.query("SELECT s.id,s.variant_id,s.serial_number,s.lot_id,s.status,s.created_at,s.updated_at,s.version,COALESCE(sum(b.on_hand_quantity),0),max(b.warehouse_id::text)::uuid,max(b.location_id::text)::uuid FROM inventory_serials s LEFT JOIN inventory_balances b ON b.tenant_id=s.tenant_id AND b.serial_id=s.id WHERE s.tenant_id=? AND (?::uuid IS NULL OR s.variant_id=?::uuid) AND (?::uuid IS NULL OR s.lot_id=?::uuid) AND (?::text IS NULL OR s.status=?::text) AND (?::text IS NULL OR s.normalized_serial_number=upper(trim(?::text))) GROUP BY s.id ORDER BY "+order+",s.id OFFSET ? LIMIT ?",this::serialRow,a.tenantId(),variant,variant,lot,lot,status,status,number,number,page*size,size);}
 @Transactional(readOnly=true)LotView getLot(UUID id){var a=auth.require(Permission.INVENTORY_TRACEABILITY_READ);return lot(a.tenantId(),id);}@Transactional(readOnly=true)SerialView getSerial(UUID id){var a=auth.require(Permission.INVENTORY_TRACEABILITY_READ);return serial(a.tenantId(),id);}
 @Transactional LotView updateLot(UUID id,LocalDate made,LocalDate expiry,long version){var a=auth.require(Permission.INVENTORY_TRACEABILITY_MANAGE);dates(made,expiry);int n=jdbc.update("UPDATE inventory_lots SET manufactured_on=?,expires_on=?,updated_at=now(),version=version+1 WHERE tenant_id=? AND id=? AND version=? AND status<>'ARCHIVED'",made,expiry,a.tenantId(),id,version);if(n==0)throw error("CONCURRENT_MODIFICATION","Lot was modified or archived");audit.record(a,"LOT_UPDATED","inventory-lot",id.toString());return lot(a.tenantId(),id);}
 @Transactional LotView lotStatus(UUID id,String next,long version){var a=auth.require(Permission.INVENTORY_TRACEABILITY_MANAGE);if(next.equals("ARCHIVED")&&onHand("lot_id",a.tenantId(),id).signum()>0)throw error("LOT_HAS_ON_HAND","Lot has physical on-hand");transition("inventory_lots",a.tenantId(),id,next,version);audit.record(a,"LOT_"+next+(next.equals("ACTIVE")?"D":""),"inventory-lot",id.toString());return lot(a.tenantId(),id);}
 @Transactional SerialView serialStatus(UUID id,String next,long version){var a=auth.require(Permission.INVENTORY_TRACEABILITY_MANAGE);if(next.equals("ARCHIVED")&&onHand("serial_id",a.tenantId(),id).signum()>0)throw error("SERIAL_HAS_ON_HAND","Serial has physical on-hand");transition("inventory_serials",a.tenantId(),id,next,version);audit.record(a,"SERIAL_"+next+(next.equals("ACTIVE")?"D":""),"inventory-serial",id.toString());return serial(a.tenantId(),id);}
 Resolution resolve(UUID tenant,UUID variantId,UUID lotId,UUID serialId,String mode){if(mode.equals("NONE")){if(lotId!=null)throw error("LOT_NOT_ALLOWED","Lot is not allowed");if(serialId!=null)throw error("SERIAL_NOT_ALLOWED","Serial is not allowed");return new Resolution(null,null);}if(mode.equals("LOT")){if(lotId==null)throw error("LOT_REQUIRED","Lot is required");if(serialId!=null)throw error("SERIAL_NOT_ALLOWED","Serial is not allowed");lotFor(tenant,variantId,lotId);return new Resolution(lotId,null);}if(mode.equals("SERIAL")){if(lotId!=null)throw error("LOT_NOT_ALLOWED","Lot is not allowed");if(serialId==null)throw error("SERIAL_REQUIRED","Serial is required");serialFor(tenant,variantId,serialId,null);return new Resolution(null,serialId);}if(lotId==null)throw error("LOT_REQUIRED","Lot is required");if(serialId==null)throw error("SERIAL_REQUIRED","Serial is required");lotFor(tenant,variantId,lotId);serialFor(tenant,variantId,serialId,lotId);return new Resolution(lotId,serialId);}
 private CatalogInventoryLookup.InventoryVariant variant(UUID t,UUID v){return catalog.findInventoryVariant(t,v).orElseThrow(()->error("VARIANT_NOT_INVENTORY_ELIGIBLE","Variant not found"));}private void lotFor(UUID t,UUID v,UUID l){if(jdbc.queryForObject("SELECT count(*) FROM inventory_lots WHERE tenant_id=? AND variant_id=? AND id=? AND status<>'ARCHIVED'",Integer.class,t,v,l)==0)throw error("LOT_VARIANT_MISMATCH","Lot is missing, archived or belongs to another variant");}private void serialFor(UUID t,UUID v,UUID s,UUID l){if(jdbc.queryForObject("SELECT count(*) FROM inventory_serials WHERE tenant_id=? AND variant_id=? AND id=? AND status<>'ARCHIVED' AND (?::uuid IS NULL OR lot_id=?::uuid)",Integer.class,t,v,s,l,l)==0)throw error("SERIAL_VARIANT_MISMATCH","Serial is missing, archived or mismatched");}
 private LotView lot(UUID t,UUID id){var x=jdbc.query("SELECT id,variant_id,lot_number,manufactured_on,expires_on,status,created_at,updated_at,version FROM inventory_lots WHERE tenant_id=? AND id=?",this::lotRow,t,id);if(x.isEmpty())throw error("LOT_NOT_FOUND","Lot not found");return x.getFirst();}private SerialView serial(UUID t,UUID id){var x=jdbc.query("SELECT s.id,s.variant_id,s.serial_number,s.lot_id,s.status,s.created_at,s.updated_at,s.version,COALESCE(sum(b.on_hand_quantity),0),max(b.warehouse_id::text)::uuid,max(b.location_id::text)::uuid FROM inventory_serials s LEFT JOIN inventory_balances b ON b.tenant_id=s.tenant_id AND b.serial_id=s.id WHERE s.tenant_id=? AND s.id=? GROUP BY s.id",this::serialRow,t,id);if(x.isEmpty())throw error("SERIAL_NOT_FOUND","Serial not found");return x.getFirst();}
 private LotView lotRow(ResultSet r,int n)throws SQLException{LocalDate e=r.getObject(5,LocalDate.class);return new LotView((UUID)r.getObject(1),(UUID)r.getObject(2),r.getString(3),r.getObject(4,LocalDate.class),e,r.getString(6),e==null?"NO_EXPIRY":e.isBefore(LocalDate.now())?"EXPIRED":"VALID",r.getTimestamp(7).toInstant(),r.getTimestamp(8).toInstant(),r.getLong(9));}private SerialView serialRow(ResultSet r,int n)throws SQLException{return new SerialView((UUID)r.getObject(1),(UUID)r.getObject(2),r.getString(3),(UUID)r.getObject(4),r.getString(5),r.getBigDecimal(9),(UUID)r.getObject(10),(UUID)r.getObject(11),r.getTimestamp(6).toInstant(),r.getTimestamp(7).toInstant(),r.getLong(8));}
 private void transition(String table,UUID t,UUID id,String next,long v){if(!Set.of("ACTIVE","BLOCKED","ARCHIVED").contains(next))throw error("INVALID_TRACEABILITY_STATUS","Invalid status");int n=jdbc.update("UPDATE "+table+" SET status=?,updated_at=now(),version=version+1 WHERE tenant_id=? AND id=? AND version=? AND status<>'ARCHIVED'",next,t,id,v);if(n==0)throw error("CONCURRENT_MODIFICATION","Identity was modified or archived");}private java.math.BigDecimal onHand(String col,UUID t,UUID id){return jdbc.queryForObject("SELECT COALESCE(sum(on_hand_quantity),0) FROM inventory_balances WHERE tenant_id=? AND "+col+"=?",java.math.BigDecimal.class,t,id);}private static void bounds(int p,int s){if(p<0||s<1||s>100)throw error("INVALID_PAGINATION","Invalid pagination");}private static String normalize(String s,String what){if(s==null||s.isBlank()||s.length()>128||s.chars().anyMatch(Character::isISOControl))throw error("INVALID_"+what.toUpperCase()+"_NUMBER","Invalid "+what+" number");return s.trim().toUpperCase(Locale.ROOT);}private static void dates(LocalDate m,LocalDate e){if(m!=null&&e!=null&&e.isBefore(m))throw error("INVALID_LOT_DATES","Expiry precedes manufacture");}private static InventoryException error(String c,String m){return new InventoryException(c,m);}
 record LotCommand(UUID variantId,String lotNumber,LocalDate manufacturedOn,LocalDate expiresOn){}record SerialCommand(UUID variantId,String serialNumber,UUID lotId){}record Resolution(UUID lotId,UUID serialId){}record LotView(UUID id,UUID variantId,String lotNumber,LocalDate manufacturedOn,LocalDate expiresOn,String status,String expiryState,Instant createdAt,Instant updatedAt,long version){}record SerialView(UUID id,UUID variantId,String serialNumber,UUID lotId,String status,java.math.BigDecimal onHand,UUID warehouseId,UUID locationId,Instant createdAt,Instant updatedAt,long version){}
}
